-- FindBack: proposed PostgreSQL DDL for Jira review (not an Alembic migration).
-- Prerequisites: public.posts exists, posts.id is UUID, posts.type uses LOST/FOUND.
-- UUIDs are generated by the application; no PostgreSQL extension is required.
-- Run categories first when integrating Posts, then let Posts create category_id/FK.
-- Run this complete draft only AFTER Posts exists. No existing table is modified.
-- Matching service must validate LOST/FOUND types and eligible/public post status.
-- FK alone does not validate post type. Posts must disallow type changes while
-- referenced, or invalidate related matches transactionally before changing type.
BEGIN;

CREATE TABLE public.categories (
    id UUID PRIMARY KEY,
    name VARCHAR(100) NOT NULL CHECK (btrim(name) <> ''),
    slug VARCHAR(100) NOT NULL UNIQUE
        CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE public.categories IS
    'Flat item categories. Disable categories instead of deleting referenced rows.';

CREATE TABLE public.matches (
    id UUID PRIMARY KEY,
    lost_post_id UUID NOT NULL,
    found_post_id UUID NOT NULL,
    score NUMERIC(5,2) NOT NULL,
    score_details JSONB NOT NULL,
    explanation TEXT NOT NULL CHECK (btrim(explanation) <> ''),
    rule_version VARCHAR(30) NOT NULL CHECK (btrim(rule_version) <> ''),
    calculated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_matches_lost_post FOREIGN KEY (lost_post_id)
        REFERENCES public.posts(id) ON DELETE RESTRICT,
    CONSTRAINT fk_matches_found_post FOREIGN KEY (found_post_id)
        REFERENCES public.posts(id) ON DELETE RESTRICT,
    CONSTRAINT uq_matches_pair UNIQUE (lost_post_id, found_post_id),
    CONSTRAINT ck_matches_different_posts CHECK (lost_post_id <> found_post_id),
    CONSTRAINT ck_matches_score CHECK (score BETWEEN 0 AND 100),
    CONSTRAINT ck_matches_score_details CHECK (jsonb_typeof(score_details) = 'object')
);

CREATE INDEX ix_matches_lost_ranking
    ON public.matches (lost_post_id, score DESC, id);
CREATE INDEX ix_matches_found_ranking
    ON public.matches (found_post_id, score DESC, id);

COMMENT ON TABLE public.matches IS
    'Rule-based suggestions only; never proof of ownership or claim approval.';
COMMENT ON COLUMN public.matches.score_details IS
    'Public criteria scores and missing-data decisions only; schema to be agreed in KAN-23.';
COMMENT ON COLUMN public.matches.rule_version IS
    'Rules used for the latest calculation; one current result per LOST/FOUND pair.';

COMMIT;

-- Posts-owned integration, to be added in its agreed Alembic migration:
-- posts.category_id UUID NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT
-- Add a posts.category_id index there. Existing data requires a backfill before NOT NULL.
-- Application updates categories.updated_at on edits, and calculated_at on recalculation.
-- Recalculation uses ON CONFLICT (lost_post_id, found_post_id) DO UPDATE,
-- updating score, score_details, explanation, rule_version and calculated_at together.
-- Recalculation must also delete/invalidate previous pairs that no longer qualify.
-- On reads, recheck current post visibility/eligibility; never expose stale hidden posts.
